### **Red-Black Tree Implementation (Java)**  
```java
class Node {
    int data;
    Node parent, left, right;
    boolean color; // true = red, false = black

    public Node(int data) {
        this.data = data;
        this.color = true; // New nodes are red by default
    }
}

public class RedBlackTree {
    private Node root;
    private final Node NIL = new Node(-1); // Sentinel node (black)

    public RedBlackTree() {
        root = NIL;
        NIL.color = false;
    }

    // Insertion
    public void insert(int data) {
        Node newNode = new Node(data);
        newNode.left = NIL;
        newNode.right = NIL;

        Node parent = null;
        Node current = root;

        // Standard BST insertion
        while (current != NIL) {
            parent = current;
            if (data < current.data) {
                current = current.left;
            } else {
                current = current.right;
            }
        }

        newNode.parent = parent;
        if (parent == null) {
            root = newNode;
        } else if (data < parent.data) {
            parent.left = newNode;
        } else {
            parent.right = newNode;
        }

        if (newNode.parent == null) {
            newNode.color = false;
            return;
        }

        if (newNode.parent.parent == null) {
            return;
        }

        fixInsert(newNode);
    }

    private void fixInsert(Node node) {
        while (node.parent.color) {
            if (node.parent == node.parent.parent.right) {
                Node uncle = node.parent.parent.left;
                if (uncle.color) {
                    uncle.color = false;
                    node.parent.color = false;
                    node.parent.parent.color = true;
                    node = node.parent.parent;
                } else {
                    if (node == node.parent.left) {
                        node = node.parent;
                        rightRotate(node);
                    }
                    node.parent.color = false;
                    node.parent.parent.color = true;
                    leftRotate(node.parent.parent);
                }
            } else {
                Node uncle = node.parent.parent.right;
                if (uncle.color) {
                    uncle.color = false;
                    node.parent.color = false;
                    node.parent.parent.color = true;
                    node = node.parent.parent;
                } else {
                    if (node == node.parent.right) {
                        node = node.parent;
                        leftRotate(node);
                    }
                    node.parent.color = false;
                    node.parent.parent.color = true;
                    rightRotate(node.parent.parent);
                }
            }
            if (node == root) break;
        }
        root.color = false;
    }

    // Deletion
    public void delete(int data) {
        Node node = search(root, data);
        if (node == NIL) return;

        Node y = node;
        boolean yOriginalColor = y.color;
        Node x;

        if (node.left == NIL) {
            x = node.right;
            transplant(node, node.right);
        } else if (node.right == NIL) {
            x = node.left;
            transplant(node, node.left);
        } else {
            y = minimum(node.right);
            yOriginalColor = y.color;
            x = y.right;
            if (y.parent == node) {
                x.parent = y;
            } else {
                transplant(y, y.right);
                y.right = node.right;
                y.right.parent = y;
            }
            transplant(node, y);
            y.left = node.left;
            y.left.parent = y;
            y.color = node.color;
        }

        if (!yOriginalColor) {
            fixDelete(x);
        }
    }

    private void fixDelete(Node x) {
        while (x != root && !x.color) {
            if (x == x.parent.left) {
                Node sibling = x.parent.right;
                if (sibling.color) {
                    sibling.color = false;
                    x.parent.color = true;
                    leftRotate(x.parent);
                    sibling = x.parent.right;
                }
                if (!sibling.left.color && !sibling.right.color) {
                    sibling.color = true;
                    x = x.parent;
                } else {
                    if (!sibling.right.color) {
                        sibling.left.color = false;
                        sibling.color = true;
                        rightRotate(sibling);
                        sibling = x.parent.right;
                    }
                    sibling.color = x.parent.color;
                    x.parent.color = false;
                    sibling.right.color = false;
                    leftRotate(x.parent);
                    x = root;
                }
            } else {
                Node sibling = x.parent.left;
                if (sibling.color) {
                    sibling.color = false;
                    x.parent.color = true;
                    rightRotate(x.parent);
                    sibling = x.parent.left;
                }
                if (!sibling.left.color && !sibling.right.color) {
                    sibling.color = true;
                    x = x.parent;
                } else {
                    if (!sibling.left.color) {
                        sibling.right.color = false;
                        sibling.color = true;
                        leftRotate(sibling);
                        sibling = x.parent.left;
                    }
                    sibling.color = x.parent.color;
                    x.parent.color = false;
                    sibling.left.color = false;
                    rightRotate(x.parent);
                    x = root;
                }
            }
        }
        x.color = false;
    }

    // Helper methods
    private Node search(Node root, int data) {
        if (root == NIL || root.data == data) return root;
        if (data < root.data) return search(root.left, data);
        return search(root.right, data);
    }

    private Node minimum(Node node) {
        while (node.left != NIL) node = node.left;
        return node;
    }

    private void transplant(Node u, Node v) {
        if (u.parent == null) root = v;
        else if (u == u.parent.left) u.parent.left = v;
        else u.parent.right = v;
        v.parent = u.parent;
    }

    private void leftRotate(Node x) {
        Node y = x.right;
        x.right = y.left;
        if (y.left != NIL) y.left.parent = x;
        y.parent = x.parent;
        if (x.parent == null) root = y;
        else if (x == x.parent.left) x.parent.left = y;
        else x.parent.right = y;
        y.left = x;
        x.parent = y;
    }

    private void rightRotate(Node x) {
        Node y = x.left;
        x.left = y.right;
        if (y.right != NIL) y.right.parent = x;
        y.parent = x.parent;
        if (x.parent == null) root = y;
        else if (x == x.parent.right) x.parent.right = y;
        else x.parent.left = y;
        y.right = x;
        x.parent = y;
    }

    // Test the implementation
    public static void main(String[] args) {
        RedBlackTree tree = new RedBlackTree();
        tree.insert(10);
        tree.insert(20);
        tree.insert(30);
        tree.insert(15);
        tree.delete(20);
        System.out.println("Red-Black Tree operations completed.");
    }
}
